const double omega0_cpp = hc_get("omega0", 2.0);
const double shared_period = hc_get("rabi_period", 0.0);
const double shared_area = hc_get("pulse_area", 0.0);
const std::string sample_label = hc_get("sample_label", std::string("Two-level medium A"));
if (shared_period <= 0.0 || shared_area <= 0.0) {
    throw std::runtime_error("Run the shared parameter cell before this C++ cell");
}
const double t1_cpp = hc_get("T1", 8.0);
const double pi_cpp = std::acos(-1.0);
const double rabi_period_cpp = 2.0 * pi_cpp / omega0_cpp;
const double rabi_period_error_cpp = std::fabs(rabi_period_cpp - shared_period);
hc_set("rabi_period_cpp", rabi_period_cpp);
hc_set("rabi_period_error_cpp", rabi_period_error_cpp);
std::cout << "Sample: " << sample_label << std::endl;
std::cout << "C++ Rabi period = " << rabi_period_cpp
          << ", Python period = " << shared_period
          << ", absolute error = " << rabi_period_error_cpp << std::endl;
std::cout << "Shared pulse area = " << shared_area
          << ", T1 = " << t1_cpp << std::endl;

omega0_oct = hc_get("omega0", 2.0);
shared_period = hc_get("rabi_period", 0.0);
cpp_period = hc_get("rabi_period_cpp", 0.0);
sample_label = hc_get("sample_label", "Two-level medium A");
if shared_period <= 0 || cpp_period <= 0
    error("Run the Python parameter cell and C++ validation cell first")
end
T1_oct = hc_get("T1", 8.0);
rabi_period_oct = 2 * pi / omega0_oct;
period_max_error = max(abs([shared_period, cpp_period, rabi_period_oct] - shared_period));
hc_set("rabi_period_octave", rabi_period_oct);
hc_set("period_max_error", period_max_error);
fprintf("Sample: %s\n", sample_label);
fprintf("Octave Rabi period = %.12f, C++ period = %.12f\n", rabi_period_oct, cpp_period);
fprintf("Maximum cross-language period error = %.3g, T1 = %.4f\n", period_max_error, T1_oct);
